{
  "name": "aaims",
  "version": "0.1.0",
  "private": true,
  "description": "AAIMS (AIMI) — Australian AI Management & Safety Interface POC",
  "workspaces": [
    "server",
    "client"
  ],
  "scripts": {
    "dev:server": "npm run dev --workspace=server",
    "dev:client": "npm run dev --workspace=client",
    "build": "npm run build --workspaces --if-present",
    "start:server": "npm run start --workspace=server",
    "start:client": "npm run dev --workspace=client",
    "test:api": "node tests/api.test.js",
    "test:e2e": "playwright test",
    "install:all": "npm install"
  },
  "devDependencies": {
    "@playwright/test": "^1.49.1",
    "@types/node": "^22.10.0"
  },
  "engines": {
    "node": ">=22.0.0"
  }
}

{
  "name": "aaims-server",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "tsx watch src/server.ts",
    "build": "tsc",
    "start": "node dist/server.js"
  },
  "dependencies": {
    "@bitbop/sdk": "https://www.bitbop.dev/downloads/bitbop-sdk-2.1.0.tgz",
    "cors": "^2.8.5",
    "express": "^4.21.2",
    "mlkem": "^2.0.0",
    "uuid": "^11.0.5"
  },
  "devDependencies": {
    "@types/cors": "^2.8.17",
    "@types/express": "^5.0.0",
    "@types/node": "^22.10.5",
    "tsx": "^4.19.2",
    "typescript": "^5.7.3"
  }
}

{
  "name": "@aaims/client",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite --port 5173 --strictPort",
    "build": "tsc -b && vite build",
    "preview": "vite preview --port 5173 --strictPort"
  },
  "dependencies": {
    "react": "^19.0.0",
    "react-dom": "^19.0.0"
  },
  "devDependencies": {
    "@types/react": "^19.0.0",
    "@types/react-dom": "^19.0.0",
    "@vitejs/plugin-react": "^4.3.4",
    "typescript": "^5.7.2",
    "vite": "^6.0.0"
  }
}

/** AAIMS Three-Object Domain Model & Governance Types */

export type SolutionStage =
  | 'REQUEST'
  | 'INVESTIGATE'
  | 'ASSIGN_OWNER'
  | 'IDENTIFY_CAPABILITIES'
  | 'APPLY_CONTROLS'
  | 'ASSESS'
  | 'APPROVE'
  | 'IMPLEMENT'
  | 'REVIEW';

export const SOLUTION_STAGE_ORDER: SolutionStage[] = [
  'REQUEST',
  'INVESTIGATE',
  'ASSIGN_OWNER',
  'IDENTIFY_CAPABILITIES',
  'APPLY_CONTROLS',
  'ASSESS',
  'APPROVE',
  'IMPLEMENT',
  'REVIEW',
];

export const STAGE_INDEX: Record<SolutionStage, number> = Object.fromEntries(
  SOLUTION_STAGE_ORDER.map((s, i) => [s, i + 1])
) as Record<SolutionStage, number>;

export type RiskTier = 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';

export type CapabilityStatus = 'DRAFT' | 'AUTHORISED' | 'SUSPENDED' | 'RETIRED';

export type ControlStatus = 'ACTIVE' | 'INACTIVE' | 'PENDING';

export interface NamedOwner {
  name: string;
  email: string;
  role?: string;
}

export interface Solution {
  id: string;
  title: string;
  description: string;
  stage: SolutionStage;
  riskTier: RiskTier;
  owner: NamedOwner;
  capabilityIds: string[];
  createdAt: string;
  updatedAt: string;
}

export interface Capability {
  id: string;
  name: string;
  description: string;
  status: CapabilityStatus;
  owner: NamedOwner;
  controlIds: string[];
  naicGuardrailIds: string[];
  createdAt: string;
  updatedAt: string;
}

export interface Control {
  id: string;
  name: string;
  description: string;
  status: ControlStatus;
  owner: NamedOwner;
  capabilityId: string;
  guardrailRef?: string;
  essentialPracticeRef?: string;
  createdAt: string;
  updatedAt: string;
}

export type RequestStatus = 'OPEN' | 'IN_PROGRESS' | 'CLOSED';

export interface GovernanceRequest {
  id: string;
  title: string;
  description: string;
  status: RequestStatus;
  requester: NamedOwner;
  solutionId?: string;
  createdAt: string;
  updatedAt: string;
}

export interface MeetingDecision {
  id: string;
  title: string;
  decision: string;
  attendees: string[];
  solutionId?: string;
  decidedAt: string;
  createdAt: string;
}

export interface RiskAssessment {
  id: string;
  solutionId: string;
  riskTier: RiskTier;
  naicAlignment: string;
  findings: string;
  assessor: NamedOwner;
  assessedAt: string;
  createdAt: string;
}

export type BreachSeverity = 'MINOR' | 'MODERATE' | 'MAJOR' | 'CRITICAL';
export type BreachStatus = 'REPORTED' | 'INVESTIGATING' | 'REMEDIATING' | 'CLOSED';

export interface Breach {
  id: string;
  title: string;
  description: string;
  severity: BreachSeverity;
  status: BreachStatus;
  capabilityId?: string;
  controlId?: string;
  reporter: NamedOwner;
  reportedAt: string;
  createdAt: string;
  updatedAt: string;
}

export type RemediationStatus = 'PLANNED' | 'IN_PROGRESS' | 'COMPLETED' | 'VERIFIED';

export interface Remediation {
  id: string;
  breachId: string;
  action: string;
  status: RemediationStatus;
  owner: NamedOwner;
  dueDate?: string;
  completedAt?: string;
  createdAt: string;
  updatedAt: string;
}

export interface ComplianceAudit {
  id: string;
  title: string;
  checklist: ComplianceCheckItem[];
  auditor: NamedOwner;
  status: 'DRAFT' | 'IN_PROGRESS' | 'COMPLETED';
  completedAt?: string;
  createdAt: string;
  updatedAt: string;
}

export interface ComplianceCheckItem {
  id: string;
  label: string;
  passed: boolean;
  notes?: string;
}

export interface NaicGuardrail {
  id: string;
  code: string;
  title: string;
  description: string;
  environment: 'DEV' | 'DEP' | 'BOTH';
}

export interface EssentialPractice {
  id: string;
  code: string;
  title: string;
  description: string;
}

export interface WorkingGroupNode {
  id: string;
  name: string;
  parentId: string | null;
  role: string;
}

export interface BitbopAttestation {
  id: string;
  eventType: string;
  entityType: string;
  entityId: string;
  beaconSequence: number;
  receipt: Record<string, unknown>;
  verified: boolean;
  createdAt: string;
}

export interface ApprovalAuthority {
  riskTier: RiskTier;
  requiredRole: string;
  description: string;
}

export const APPROVAL_AUTHORITIES: ApprovalAuthority[] = [
  { riskTier: 'LOW', requiredRole: 'Team Lead', description: 'Team Lead may approve low-risk solutions' },
  { riskTier: 'MEDIUM', requiredRole: 'Working Group Chair', description: 'WG Chair required for medium risk' },
  { riskTier: 'HIGH', requiredRole: 'AI Governance Board', description: 'Board approval for high risk' },
  { riskTier: 'CRITICAL', requiredRole: 'Executive Sponsor', description: 'Executive sponsor for critical risk' },
];

export const GOVERNANCE_EVENT_TYPES = [
  'solution_stage_advance',
  'capability_authorised',
  'control_activated',
  'meeting_decision',
  'risk_assessment',
  'breach_reported',
  'compliance_audit_completed',
] as const;

export type GovernanceEventType = (typeof GOVERNANCE_EVENT_TYPES)[number];

import { DatabaseSync } from 'node:sqlite';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import type {
  Solution,
  Capability,
  Control,
  GovernanceRequest,
  MeetingDecision,
  RiskAssessment,
  Breach,
  Remediation,
  ComplianceAudit,
  SolutionStage,
  CapabilityStatus,
  RiskTier,
} from './types.js';

const DB_PATH = path.join(process.cwd(), 'data', 'aaims.db');

let db: DatabaseSync;

export function getDb(): DatabaseSync {
  if (!db) {
    db = new DatabaseSync(DB_PATH);
    db.exec('PRAGMA foreign_keys = ON;');
    initSchema(db);
  }
  return db;
}

function initSchema(database: DatabaseSync): void {
  database.exec(`
    CREATE TABLE IF NOT EXISTS solutions (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      owner_name TEXT NOT NULL,
      stage INTEGER NOT NULL DEFAULT 1 CHECK(stage BETWEEN 1 AND 9),
      risk_tier TEXT NOT NULL DEFAULT 'LOW' CHECK(risk_tier IN ('LOW','MEDIUM','HIGH','CRITICAL')),
      approved_by TEXT,
      approved_at TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS capabilities (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      owner_name TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','IN_REVIEW','AUTHORISED','SUSPENDED','RETIRED')),
      category TEXT NOT NULL DEFAULT '',
      naic_ref TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS controls (
      id TEXT PRIMARY KEY,
      capability_id TEXT NOT NULL REFERENCES capabilities(id) ON DELETE CASCADE,
      name TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      owner_name TEXT NOT NULL,
      control_type TEXT NOT NULL DEFAULT 'PREVENTIVE',
      guardrail_id TEXT,
      environment TEXT CHECK(environment IN ('DEV','DEP',NULL)),
      active INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS solution_capabilities (
      solution_id TEXT NOT NULL REFERENCES solutions(id) ON DELETE CASCADE,
      capability_id TEXT NOT NULL REFERENCES capabilities(id) ON DELETE CASCADE,
      linked_at TEXT NOT NULL,
      PRIMARY KEY (solution_id, capability_id)
    );

    CREATE TABLE IF NOT EXISTS governance_requests (
      id TEXT PRIMARY KEY,
      solution_id TEXT REFERENCES solutions(id) ON DELETE SET NULL,
      title TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      requester_name TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'OPEN',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS meeting_decisions (
      id TEXT PRIMARY KEY,
      solution_id TEXT REFERENCES solutions(id) ON DELETE SET NULL,
      meeting_date TEXT NOT NULL,
      decision TEXT NOT NULL,
      attendees TEXT NOT NULL DEFAULT '[]',
      recorded_by TEXT NOT NULL,
      created_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS risk_assessments (
      id TEXT PRIMARY KEY,
      solution_id TEXT NOT NULL REFERENCES solutions(id) ON DELETE CASCADE,
      assessor_name TEXT NOT NULL,
      risk_tier TEXT NOT NULL CHECK(risk_tier IN ('LOW','MEDIUM','HIGH','CRITICAL')),
      naic_alignment TEXT NOT NULL DEFAULT '',
      findings TEXT NOT NULL DEFAULT '',
      assessed_at TEXT NOT NULL,
      created_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS breaches (
      id TEXT PRIMARY KEY,
      solution_id TEXT REFERENCES solutions(id) ON DELETE SET NULL,
      capability_id TEXT REFERENCES capabilities(id) ON DELETE SET NULL,
      title TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      severity TEXT NOT NULL DEFAULT 'MEDIUM',
      reported_by TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'OPEN',
      detected_at TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS remediations (
      id TEXT PRIMARY KEY,
      breach_id TEXT NOT NULL REFERENCES breaches(id) ON DELETE CASCADE,
      action TEXT NOT NULL,
      owner_name TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'PLANNED',
      due_date TEXT,
      completed_at TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS compliance_audits (
      id TEXT PRIMARY KEY,
      solution_id TEXT REFERENCES solutions(id) ON DELETE SET NULL,
      auditor_name TEXT NOT NULL,
      checklist_json TEXT NOT NULL DEFAULT '[]',
      overall_status TEXT NOT NULL DEFAULT 'IN_PROGRESS',
      notes TEXT NOT NULL DEFAULT '',
      audited_at TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS bitbop_attestations (
      id TEXT PRIMARY KEY,
      event_type TEXT NOT NULL,
      entity_type TEXT NOT NULL,
      entity_id TEXT NOT NULL,
      beacon_sequence INTEGER NOT NULL,
      receipt_json TEXT NOT NULL,
      verified INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL
    );

    CREATE INDEX IF NOT EXISTS idx_controls_capability ON controls(capability_id);
    CREATE INDEX IF NOT EXISTS idx_solution_capabilities_solution ON solution_capabilities(solution_id);
    CREATE INDEX IF NOT EXISTS idx_solution_capabilities_capability ON solution_capabilities(capability_id);
  `);
}

function now(): string {
  return new Date().toISOString();
}

function rowToSolution(row: Record<string, unknown>): Solution {
  return {
    id: row.id as string,
    title: row.title as string,
    description: row.description as string,
    ownerName: row.owner_name as string,
    stage: row.stage as SolutionStage,
    riskTier: row.risk_tier as RiskTier,
    approvedBy: (row.approved_by as string) ?? undefined,
    approvedAt: (row.approved_at as string) ?? undefined,
    createdAt: row.created_at as string,
    updatedAt: row.updated_at as string,
  };
}

function rowToCapability(row: Record<string, unknown>): Capability {
  return {
    id: row.id as string,
    name: row.name as string,
    description: row.description as string,
    ownerName: row.owner_name as string,
    status: row.status as CapabilityStatus,
    category: row.category as string,
    naicRef: (row.naic_ref as string) ?? undefined,
    createdAt: row.created_at as string,
    updatedAt: row.updated_at as string,
  };
}

function rowToControl(row: Record<string, unknown>): Control {
  return {
    id: row.id as string,
    capabilityId: row.capability_id as string,
    name: row.name as string,
    description: row.description as string,
    ownerName: row.owner_name as string,
    controlType: row.control_type as string,
    guardrailId: (row.guardrail_id as string) ?? undefined,
    environment: (row.environment as 'DEV' | 'DEP') ?? undefined,
    active: Boolean(row.active),
    createdAt: row.created_at as string,
    updatedAt: row.updated_at as string,
  };
}

export function listSolutions(): Solution[] {
  const rows = getDb().prepare('SELECT * FROM solutions ORDER BY updated_at DESC').all();
  return rows.map((r) => rowToSolution(r as Record<string, unknown>));
}

export function getSolution(id: string): Solution | null {
  const row = getDb().prepare('SELECT * FROM solutions WHERE id = ?').get(id);
  return row ? rowToSolution(row as Record<string, unknown>) : null;
}

export function createSolution(input: Omit<Solution, 'id' | 'createdAt' | 'updatedAt'>): Solution {
  const id = randomUUID();
  const ts = now();
  getDb().prepare(
    `INSERT INTO solutions (id, title, description, owner_name, stage, risk_tier, approved_by, approved_at, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).run(id, input.title, input.description, input.ownerName, input.stage, input.riskTier, input.approvedBy ?? null, input.approvedAt ?? null, ts, ts);
  return getSolution(id)!;
}

export function updateSolution(id: string, patch: Partial<Omit<Solution, 'id' | 'createdAt'>>): Solution | null {
  const existing = getSolution(id);
  if (!existing) return null;
  const merged = { ...existing, ...patch, updatedAt: now() };
  getDb().prepare(
    `UPDATE solutions SET title=?, description=?, owner_name=?, stage=?, risk_tier=?, approved_by=?, approved_at=?, updated_at=? WHERE id=?`
  ).run(
    merged.title,
    merged.description,
    merged.ownerName,
    merged.stage,
    merged.riskTier,
    merged.approvedBy ?? null,
    merged.approvedAt ?? null,
    merged.updatedAt,
    id
  );
  return getSolution(id);
}

export function listCapabilities(): Capability[] {
  const rows = getDb().prepare('SELECT * FROM capabilities ORDER BY name').all();
  return rows.map((r) => rowToCapability(r as Record<string, unknown>));
}

export function getCapability(id: string): Capability | null {
  const row = getDb().prepare('SELECT * FROM capabilities WHERE id = ?').get(id);
  return row ? rowToCapability(row as Record<string, unknown>) : null;
}

export function createCapability(input: Omit<Capability, 'id' | 'createdAt' | 'updatedAt'>): Capability {
  const id = randomUUID();
  const ts = now();
  getDb().prepare(
    `INSERT INTO capabilities (id, name, description, owner_name, status, category, naic_ref, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).run(id, input.name, input.description, input.ownerName, input.status, input.category, input.naicRef ?? null, ts, ts);
  return getCapability(id)!;
}

export function updateCapability(id: string, patch: Partial<Omit<Capability, 'id' | 'createdAt'>>): Capability | null {
  const existing = getCapability(id);
  if (!existing) return null;
  const merged = { ...existing, ...patch, updatedAt: now() };
  getDb().prepare(
    `UPDATE capabilities SET name=?, description=?, owner_name=?, status=?, category=?, naic_ref=?, updated_at=? WHERE id=?`
  ).run(merged.name, merged.description, merged.ownerName, merged.status, merged.category, merged.naicRef ?? null, merged.updatedAt, id);
  return getCapability(id);
}

export function listControls(capabilityId?: string): Control[] {
  if (capabilityId) {
    const rows = getDb().prepare('SELECT * FROM controls WHERE capability_id = ? ORDER BY name').all(capabilityId);
    return rows.map((r) => rowToControl(r as Record<string, unknown>));
  }
  const rows = getDb().prepare('SELECT * FROM controls ORDER BY name').all();
  return rows.map((r) => rowToControl(r as Record<string, unknown>));
}

export function getControl(id: string): Control | null {
  const row = getDb().prepare('SELECT * FROM controls WHERE id = ?').get(id);
  return row ? rowToControl(row as Record<string, unknown>) : null;
}

export function createControl(input: Omit<Control, 'id' | 'createdAt' | 'updatedAt'>): Control {
  const id = randomUUID();
  const ts = now();
  getDb().prepare(
    `INSERT INTO controls (id, capability_id, name, description, owner_name, control_type, guardrail_id, environment, active, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).run(
    id,
    input.capabilityId,
    input.name,
    input.description,
    input.ownerName,
    input.controlType,
    input.guardrailId ?? null,
    input.environment ?? null,
    input.active ? 1 : 0,
    ts,
    ts
  );
  return getControl(id)!;
}

export function updateControl(id: string, patch: Partial<Omit<Control, 'id' | 'createdAt'>>): Control | null {
  const existing = getControl(id);
  if (!existing) return null;
  const merged = { ...existing, ...patch, updatedAt: now() };
  getDb().prepare(
    `UPDATE controls SET capability_id=?, name=?, description=?, owner_name=?, control_type=?, guardrail_id=?, environment=?, active=?, updated_at=? WHERE id=?`
  ).run(
    merged.capabilityId,
    merged.name,
    merged.description,
    merged.ownerName,
    merged.controlType,
    merged.guardrailId ?? null,
    merged.environment ?? null,
    merged.active ? 1 : 0,
    merged.updatedAt,
    id
  );
  return getControl(id);
}

export function linkCapabilityToSolution(solutionId: string, capabilityId: string): void {
  getDb().prepare(
    `INSERT OR IGNORE INTO solution_capabilities (solution_id, capability_id, linked_at) VALUES (?, ?, ?)`
  ).run(solutionId, capabilityId, now());
}

export function unlinkCapabilityFromSolution(solutionId: string, capabilityId: string): void {
  getDb().prepare(
    `DELETE FROM solution_capabilities WHERE solution_id = ? AND capability_id = ?`
  ).run(solutionId, capabilityId);
}

export function getSolutionCapabilities(solutionId: string): Capability[] {
  const rows = getDb().prepare(
    `SELECT c.* FROM capabilities c
     JOIN solution_capabilities sc ON sc.capability_id = c.id
     WHERE sc.solution_id = ? ORDER BY c.name`
  ).all(solutionId);
  return rows.map((r) => rowToCapability(r as Record<string, unknown>));
}

export function countSolutionCapabilities(solutionId: string): number {
  const row = getDb().prepare(
    `SELECT COUNT(*) AS cnt FROM solution_capabilities WHERE solution_id = ?`
  ).get(solutionId) as { cnt: number };
  return row.cnt;
}

export function countActiveControlsForCapability(capabilityId: string): number {
  const row = getDb().prepare(
    `SELECT COUNT(*) AS cnt FROM controls WHERE capability_id = ? AND active = 1`
  ).get(capabilityId) as { cnt: number };
  return row.cnt;
}

export function allLinkedCapabilitiesHaveActiveControls(solutionId: string): boolean {
  const caps = getSolutionCapabilities(solutionId);
  if (caps.length === 0) return false;
  return caps.every((c) => countActiveControlsForCapability(c.id) > 0);
}

export function countSolutionControls(solutionId: string): number {
  const row = getDb().prepare(
    `SELECT COUNT(*) AS cnt FROM controls ctl
     JOIN solution_capabilities sc ON sc.capability_id = ctl.capability_id
     WHERE sc.solution_id = ?`
  ).get(solutionId) as { cnt: number };
  return row.cnt;
}

export function createGovernanceRequest(input: Omit<GovernanceRequest, 'id' | 'createdAt' | 'updatedAt'>): GovernanceRequest {
  const id = randomUUID();
  const ts = now();
  getDb().prepare(
    `INSERT INTO governance_requests (id, solution_id, title, description, requester_name, status, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
  ).run(id, input.solutionId ?? null, input.title, input.description, input.requesterName, input.status, ts, ts);
  return { ...input, id, createdAt: ts, updatedAt: ts };
}

export function listGovernanceRequests(): GovernanceRequest[] {
  return getDb().prepare('SELECT * FROM governance_requests ORDER BY created_at DESC').all() as GovernanceRequest[];
}

export function createMeetingDecision(input: Omit<MeetingDecision, 'id' | 'createdAt'>): MeetingDecision {
  const id = randomUUID();
  const ts = now();
  getDb().prepare(
    `INSERT INTO meeting_decisions (id, solution_id, meeting_date, decision, attendees, recorded_by, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?)`
  ).run(id, input.solutionId ?? null, input.meetingDate, input.decision, JSON.stringify(input.attendees), input.recordedBy, ts);
  return { ...input, id, createdAt: ts };
}

export function listMeetingDecisions(): MeetingDecision[] {
  const rows = getDb().prepare('SELECT * FROM meeting_decisions ORDER BY meeting_date DESC').all() as Array<Record<string, unknown>>;
  return rows.map((r) => ({
    id: r.id as string,
    solutionId: (r.solution_id as string) ?? undefined,
    meetingDate: r.meeting_date as string,
    decision: r.decision as string,
    attendees: JSON.parse(r.attendees as string) as string[],
    recordedBy: r.recorded_by as string,
    createdAt: r.created_at as string,
  }));
}

export function createRiskAssessment(input: Omit<RiskAssessment, 'id' | 'createdAt'>): RiskAssessment {
  const id = randomUUID();
  const ts = now();
  getDb().prepare(
    `INSERT INTO risk_assessments (id, solution_id, assessor_name, risk_tier, naic_alignment, findings, assessed_at, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
  ).run(id, input.solutionId, input.assessorName, input.riskTier, input.naicAlignment, input.findings, input.assessedAt, ts);
  return { ...input, id, createdAt: ts };
}

export function listRiskAssessments(): RiskAssessment[] {
  return getDb().prepare('SELECT * FROM risk_assessments ORDER BY assessed_at DESC').all() as RiskAssessment[];
}

export function createBreach(input: Omit<Breach, 'id' | 'createdAt' | 'updatedAt'>): Breach {
  const id = randomUUID();
  const ts = now();
  getDb().prepare(
    `INSERT INTO breaches (id, solution_id, capability_id, title, description, severity, reported_by, status, detected_at, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).run(id, input.solutionId ?? null, input.capabilityId ?? null, input.title, input.description, input.severity, input.reportedBy, input.status, input.detectedAt, ts, ts);
