import { createDecipheriv } from 'node:crypto';
import { MlKem768 } from 'mlkem';

const BITBOP_BASE = process.env.BITBOP_API_URL ?? 'https://api.bitbop.dev';

export interface BitBopCipher {
  kyber_ciphertext_hex: string;
  aes_iv_hex: string;
  aes_ciphertext_hex: string;
}

export interface ConsumeAttestation {
  beacon_sequence: number;
  beacon_hash: string;
  beacon_byte_offset: number;
  byte_count: number;
  entropy_sha256: string;
  source_type: string;
  signature_scheme: string;
  signature: string;
}

export interface ConsumeResponse {
  version: string;
  timestamp: string;
  delivery_mechanism: string;
  cipher: BitBopCipher;
  attestation: ConsumeAttestation;
}

export interface VerifyResponse {
  valid: boolean;
  receipt_type?: string;
  checks?: Record<string, boolean>;
  error?: string;
}

export type GovernanceEventType =
  | 'request_submitted'
  | 'meeting_decision_recorded'
  | 'risk_assessment_completed'
  | 'solution_stage_advanced'
  | 'capability_authorised'
  | 'breach_logged'
  | 'compliance_audit_completed';

export interface GovernanceAttestation {
  eventType: GovernanceEventType;
  entityId: string;
  entityType: string;
  timestamp: string;
  receipt: ConsumeResponse;
  beacon_sequence: number;
  signature_scheme: string;
  verifyUrl: string;
  context?: Record<string, unknown>;
}

async function decryptCipher(
  cipher: BitBopCipher,
  secretKey: Uint8Array,
  kem: MlKem768
): Promise<Buffer> {
  const sharedSecret = await kem.decap(
    Buffer.from(cipher.kyber_ciphertext_hex, 'hex'),
    secretKey
  );
  const iv = Buffer.from(cipher.aes_iv_hex, 'hex');
  const buf = Buffer.from(cipher.aes_ciphertext_hex, 'hex');
  const decipher = createDecipheriv('aes-256-gcm', Buffer.from(sharedSecret), iv);
  decipher.setAuthTag(buf.subarray(buf.length - 16));
  return Buffer.concat([
    decipher.update(buf.subarray(0, buf.length - 16)),
    decipher.final(),
  ]);
}

export class BitBopClient {
  private readonly kem = new MlKem768();
  private apiKey: string | null = null;
  private initialized = false;

  get isReady(): boolean {
    return this.initialized && this.apiKey !== null;
  }

  get keyHint(): string | null {
    if (!this.apiKey) return null;
    return this.apiKey.slice(0, 12) + '…';
  }

  async initialize(): Promise<string> {
    if (this.initialized && this.apiKey) return this.apiKey;
    this.apiKey = await this.provisionFreeKey();
    this.initialized = true;
    return this.apiKey;
  }

  /** Self-provision free-tier API key via POST /api/keys/free (ML-KEM-768 + AES-256-GCM). */
  async provisionFreeKey(): Promise<string> {
    const [publicKey, secretKey] = await this.kem.generateKeyPair();
    const kyberPublicKeyHex = Buffer.from(publicKey).toString('hex');

    const res = await fetch(BITBOP_BASE + '/api/keys/free', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ kyber_public_key: kyberPublicKeyHex }),
    });

    if (!res.ok) {
      const body = await res.text();
      throw new Error('BitBop free key provisioning failed (' + res.status + '): ' + body);
    }

    const data = (await res.json()) as Record<string, unknown>;

    if (typeof data.api_key === 'string') {
      return data.api_key;
    }

    const cipher = (data.cipher ?? data) as BitBopCipher;
    if (!cipher.kyber_ciphertext_hex) {
      throw new Error('BitBop key response missing cipher or api_key');
    }

    const plain = await decryptCipher(cipher, secretKey, this.kem);
    const key = plain.toString('utf8').trim();
    if (!key.startsWith('bb_')) {
      throw new Error('Decrypted BitBop API key has unexpected format');
    }
    return key;
  }

  /** Draw quantum entropy and receive ML-DSA-44 signed attestation (beacon_sequence > 0). */
  async consume(bytesRequested = 32): Promise<ConsumeResponse> {
    if (!this.apiKey) {
      throw new Error('BitBop client not initialized — call initialize() first');
    }

    const [publicKey, secretKey] = await this.kem.generateKeyPair();
    const kyberPublicKeyHex = Buffer.from(publicKey).toString('hex');

    const res = await fetch(BITBOP_BASE + '/consume', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
        Authorization: 'Bearer ' + this.apiKey,
      },
      body: JSON.stringify({
        bytes_requested: bytesRequested,
        kyber_public_key: kyberPublicKeyHex,
        signature_scheme: 'ml-dsa-44',
      }),
    });

    if (!res.ok) {
      const body = await res.text();
      throw new Error('BitBop consume failed (' + res.status + '): ' + body);
    }

    const receipt = (await res.json()) as ConsumeResponse;
    await decryptCipher(receipt.cipher, secretKey, this.kem);

    if (!receipt.attestation?.beacon_sequence || receipt.attestation.beacon_sequence <= 0) {
      throw new Error('BitBop consume receipt missing valid beacon_sequence');
    }
    if (receipt.attestation.signature_scheme !== 'ml-dsa-44') {
      throw new Error('BitBop receipt must use ml-dsa-44 signature scheme');
    }

    return receipt;
  }

  /** Live verification via POST /verify (public endpoint). */
  async verify(receipt: unknown): Promise<VerifyResponse> {
    const res = await fetch(BITBOP_BASE + '/verify', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify(receipt),
    });

    if (!res.ok) {
      const body = await res.text();
      return { valid: false, error: 'HTTP ' + res.status + ': ' + body };
    }

    return (await res.json()) as VerifyResponse;
  }

  async attestGovernanceEvent(
    eventType: GovernanceEventType,
    entityId: string,
    entityType: string,
    context?: Record<string, unknown>
  ): Promise<GovernanceAttestation> {
    const bytesRequested = Math.min(1024, 32 + (eventType.length % 8));
    const receipt = await this.consume(bytesRequested);
    const seq = receipt.attestation.beacon_sequence;

    const attestation: GovernanceAttestation = {
      eventType,
      entityId,
      entityType,
      timestamp: new Date().toISOString(),
      receipt,
      beacon_sequence: seq,
      signature_scheme: receipt.attestation.signature_scheme,
      verifyUrl: 'https://www.bitbop.dev/provenance?sequence=' + String(seq),
    };
    if (context) attestation.context = context;
    return attestation;
  }

  /** Attest all seven mandatory AAIMS governance event types. */
  async attestAllGovernanceEvents(seedEntityId: string): Promise<GovernanceAttestation[]> {
    const events: Array<{ type: GovernanceEventType; entityType: string }> = [
      { type: 'request_submitted', entityType: 'request' },
      { type: 'meeting_decision_recorded', entityType: 'meeting_decision' },
      { type: 'risk_assessment_completed', entityType: 'risk_assessment' },
      { type: 'solution_stage_advanced', entityType: 'solution' },
      { type: 'capability_authorised', entityType: 'capability' },
      { type: 'breach_logged', entityType: 'breach' },
      { type: 'compliance_audit_completed', entityType: 'compliance_audit' },
    ];

    const attestations: GovernanceAttestation[] = [];
    for (const evt of events) {
      attestations.push(
        await this.attestGovernanceEvent(
          evt.type,
          seedEntityId + ':' + evt.type,
          evt.entityType
        )
      );
    }
    return attestations;
  }

  async keyStatus(): Promise<Record<string, unknown>> {
    if (!this.apiKey) {
      throw new Error('BitBop client not initialized');
    }
    const res = await fetch(BITBOP_BASE + '/api/keys/status', {
      headers: { Authorization: 'Bearer ' + this.apiKey, Accept: 'application/json' },
    });
    if (!res.ok) {
      throw new Error('BitBop key status failed (' + res.status + ')');
    }
    return res.json() as Promise<Record<string, unknown>>;
  }
}

