function asyncHandler(
  fn: (req: Request, res: Response, next: NextFunction) => Promise<void>
) {
  return (req: Request, res: Response, next: NextFunction) => {
    fn(req, res, next).catch(next);
  };
}

function badRequest(res: Response, message: string) {
  return res.status(400).json({ error: message });
}

function notFound(res: Response, entity: string) {
  return res.status(404).json({ error: `${entity} not found` });
}

function validateSolutionStageAdvance(
  solutionId: string,
  targetStage: SolutionStage
): string | null {
  const caps = getSolutionCapabilities(solutionId);

  if (targetStage > 4 && caps.length < 1) {
    return 'Solution cannot advance past Stage 4 (Identify Capabilities) without at least one linked Capability';
  }

  if (targetStage > 5 || targetStage === 7) {
    if (caps.length < 1) {
      return 'Solution requires at least one linked Capability before Stage 5+ or approval';
    }
    for (const cap of caps) {
      const active = countActiveControlsForCapability(cap.id);
      if (active < 1) {
        return `Capability "${cap.name}" must have at least one active Control before advancing past Stage 5 or approval`;
      }
    }
    const allControls = caps.flatMap((c) => getCapabilityControls(c.id));
    if (allControls.length < 1) {
      return 'Solution requires at least one Control linked to its Capabilities before Stage 5+ or approval';
    }
  }

  return null;
}

function validateCapabilityAuthorisation(
  capabilityId: string,
  status: CapabilityStatus
): string | null {
  if (status !== 'AUTHORISED') return null;
  const active = countActiveControlsForCapability(capabilityId);
  if (active < 1) {
    return 'Capability cannot be set to AUTHORISED without at least one active Control';
  }
  return null;
}

const APPROVAL_AUTHORITY: Record<RiskTier, string[]> = {
  LOW: ['Team Lead', 'Working Group Chair'],
  MEDIUM: ['Working Group Chair', 'Risk Officer'],
  HIGH: ['Risk Officer', 'Executive Sponsor'],
  CRITICAL: ['Executive Sponsor', 'Board AI Committee'],
};

function validateApprovalAuthority(
  riskTier: RiskTier,
  approverRole: string
): string | null {
  const allowed = APPROVAL_AUTHORITY[riskTier] ?? [];
  if (!allowed.includes(approverRole)) {
    return `Approver role "${approverRole}" lacks delegated authority for ${riskTier} risk tier. Allowed: ${allowed.join(', ')}`;
  }
  return null;
}

