app.post(
  '/api/solutions/:id/advance',
  asyncHandler(async (req, res) => {
    const existing = getSolution(req.params.id);
    if (!existing) return notFound(res, 'Solution');
    const targetStage = Number(req.body.stage) as SolutionStage;
    if (!targetStage || targetStage < 1 || targetStage > 9) {
      return badRequest(res, 'Invalid target stage (1-9)');
    }
    if (targetStage <= existing.stage) {
      return badRequest(res, 'Target stage must be greater than current stage');
    }
    const err = validateSolutionStageAdvance(req.params.id, targetStage);
    if (err) return badRequest(res, err);
    const updated = setSolutionStage(req.params.id, targetStage);
    const receipt = await attestGovernanceEvent(
      GOVERNANCE_EVENT_TYPES.SOLUTION_STAGE_ADVANCED,
      { solutionId: updated.id, stage: updated.stage, name: updated.name }
    );
    res.json({ solution: updated, bitbop: receipt });
  })
);

app.post(
  '/api/solutions/:id/approve',
  asyncHandler(async (req, res) => {
    const existing = getSolution(req.params.id);
    if (!existing) return notFound(res, 'Solution');
    const { approverRole, approverName } = req.body as { approverRole?: string; approverName?: string };
    if (!approverRole || !approverName) {
      return badRequest(res, 'approverRole and approverName are required');
    }
    const authErr = validateApprovalAuthority(existing.riskTier, approverRole);
    if (authErr) return badRequest(res, authErr);
    const stageErr = validateSolutionStageAdvance(req.params.id, 7);
    if (stageErr) return badRequest(res, stageErr);
    if (existing.stage < 6) {
      return badRequest(res, 'Solution must reach Stage 6 (Assess) before approval');
    }
    const updated = updateSolution(req.params.id, {
      stage: 7,
      approvedBy: approverName,
      approvedAt: new Date().toISOString(),
      status: 'APPROVED',
    });
    const receipt = await attestGovernanceEvent(
      GOVERNANCE_EVENT_TYPES.SOLUTION_APPROVED,
      { solutionId: updated.id, approverRole, approverName, riskTier: updated.riskTier }
    );
    res.json({ solution: updated, bitbop: receipt });
  })
);

