let db: DatabaseSync;

function nowIso(): string {
  return new Date().toISOString();
}

function parseJson<T>(value: string | null, fallback: T): T {
  if (!value) return fallback;
  try {
    return JSON.parse(value) as T;
  } catch {
    return fallback;
  }
}

function serializeNamedOwner(owner: NamedOwner): string {
  return JSON.stringify(owner);
}

function parseNamedOwner(value: string | null | undefined): NamedOwner {
  if (!value) return { name: 'Unknown' };
  try {
    const parsed = JSON.parse(value) as NamedOwner;
    if (parsed && typeof parsed.name === 'string') return parsed;
  } catch {
    /* legacy plain string */
  }
  return { name: value };
}

function parseNamedOwnerOptional(value: string | null | undefined): NamedOwner | undefined {
  if (!value) return undefined;
  return parseNamedOwner(value);
}

export function initDatabase(dbPath = process.env.AAIMS_DB_PATH ?? 'aaims.db'): void {
  db = new DatabaseSync(dbPath);
  db.exec('PRAGMA foreign_keys = ON;');

  db.exec(`
    CREATE TABLE IF NOT EXISTS solutions (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      owner TEXT NOT NULL,
      stage INTEGER NOT NULL DEFAULT 1,
      risk_tier TEXT NOT NULL DEFAULT 'MEDIUM',
      status TEXT NOT NULL DEFAULT 'DRAFT',
      approved_by TEXT,
      approved_at TEXT,
      metadata_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS capabilities (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      owner TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'PROPOSED',
      category TEXT NOT NULL DEFAULT 'GENERAL',
      metadata_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS controls (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      owner TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'DRAFT',
      control_type TEXT NOT NULL DEFAULT 'PREVENTIVE',
      framework_ref TEXT,
      metadata_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS solution_capabilities (
      solution_id TEXT NOT NULL REFERENCES solutions(id) ON DELETE CASCADE,
      capability_id TEXT NOT NULL REFERENCES capabilities(id) ON DELETE CASCADE,
      PRIMARY KEY (solution_id, capability_id)
    );

    CREATE TABLE IF NOT EXISTS capability_controls (
      capability_id TEXT NOT NULL REFERENCES capabilities(id) ON DELETE CASCADE,
      control_id TEXT NOT NULL REFERENCES controls(id) ON DELETE CASCADE,
      PRIMARY KEY (capability_id, control_id)
    );

    CREATE TABLE IF NOT EXISTS governance_requests (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      requester TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'OPEN',
      priority TEXT NOT NULL DEFAULT 'NORMAL',
      solution_id TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS meeting_decisions (
      id TEXT PRIMARY KEY,
      summary TEXT NOT NULL,
      details TEXT NOT NULL DEFAULT '',
      chair TEXT NOT NULL,
      decision_date TEXT NOT NULL,
      solution_id TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS risk_assessments (
      id TEXT PRIMARY KEY,
      solution_id TEXT,
      assessor TEXT NOT NULL,
      risk_tier TEXT NOT NULL,
      findings TEXT NOT NULL DEFAULT '',
      naic_alignment TEXT NOT NULL DEFAULT '',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS breaches (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      severity TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'OPEN',
      reporter TEXT NOT NULL,
      capability_id TEXT,
      control_id TEXT,
      detected_at TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS remediations (
      id TEXT PRIMARY KEY,
      breach_id TEXT NOT NULL REFERENCES breaches(id) ON DELETE CASCADE,
      action TEXT NOT NULL,
      owner TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'PLANNED',
      completed_at TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS compliance_audits (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      auditor TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'PLANNED',
      checklist_json TEXT NOT NULL DEFAULT '[]',
      findings TEXT NOT NULL DEFAULT '',
      completed_at TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
  `);

  seedIfEmpty();
}

function rowToSolution(row: Record<string, unknown>): Solution {
  return {
    id: String(row.id),
    name: String(row.name),
    description: String(row.description ?? ''),
    owner: parseNamedOwner(String(row.owner)),
    stage: Number(row.stage) as SolutionStage,
    riskTier: row.risk_tier as Solution['riskTier'],
    status: row.status as Solution['status'],
    approvedBy: parseNamedOwnerOptional(row.approved_by ? String(row.approved_by) : undefined),
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    metadata: parseJson(String(row.metadata_json ?? '{}'), {}),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

