function seedIfEmpty(): void {
  const count = db.prepare('SELECT COUNT(*) AS c FROM controls').get() as { c: number };
  if (count.c > 0) return;

  const ts = nowIso();
  const wgChair: NamedOwner = { name: 'AI Working Group Chair', role: 'Chair' };
  const riskOfficer: NamedOwner = { name: 'Chief Risk Officer', role: 'CRO' };

  const guardrails: Array<{ id: string; name: string; owner: NamedOwner; frameworkRef: string }> = [
    { id: 'ctrl-g1', name: 'G1 Accountability & Governance', owner: wgChair, frameworkRef: 'NAIC-G1' },
    { id: 'ctrl-g2', name: 'G2 Compliance & Regulatory', owner: riskOfficer, frameworkRef: 'NAIC-G2' },
    { id: 'ctrl-g3-dev', name: 'G3 Development Transparency (DEV)', owner: { name: 'Model Risk Lead' }, frameworkRef: 'NAIC-G3-DEV' },
    { id: 'ctrl-g3-dep', name: 'G3 Deployment Transparency (DEP)', owner: { name: 'Operations Lead' }, frameworkRef: 'NAIC-G3-DEP' },
    { id: 'ctrl-g4', name: 'G4 Data Quality & Provenance', owner: { name: 'Data Steward' }, frameworkRef: 'NAIC-G4' },
    { id: 'ctrl-g5', name: 'G5 Fairness & Bias Monitoring', owner: { name: 'Fairness Lead' }, frameworkRef: 'NAIC-G5' },
    { id: 'ctrl-g6', name: 'G6 Security & Resilience', owner: { name: 'CISO' }, frameworkRef: 'NAIC-G6' },
    { id: 'ctrl-g7', name: 'G7 Human Oversight', owner: wgChair, frameworkRef: 'NAIC-G7' },
    { id: 'ctrl-g8-dev', name: 'G8 Third-Party Risk (DEV)', owner: { name: 'Vendor Risk Manager' }, frameworkRef: 'NAIC-G8-DEV' },
    { id: 'ctrl-g8-dep', name: 'G8 Third-Party Risk (DEP)', owner: { name: 'Vendor Risk Manager' }, frameworkRef: 'NAIC-G8-DEP' },
  ];

  const insertControl = db.prepare(`
    INSERT INTO controls (id, name, description, owner, status, control_type, framework_ref, metadata_json, created_at, updated_at)
    VALUES (?, ?, ?, ?, 'ACTIVE', 'PREVENTIVE', ?, '{}', ?, ?)
  `);

  for (const g of guardrails) {
    insertControl.run(g.id, g.name, `NAIC May Update guardrail: ${g.name}`, serializeNamedOwner(g.owner), g.frameworkRef, ts, ts);
  }

  const ai6: Array<{ id: string; name: string; owner: NamedOwner }> = [
    { id: 'ctrl-ai6-1', name: 'AI6 Essential Practice 1 — Inventory', owner: wgChair },
    { id: 'ctrl-ai6-2', name: 'AI6 Essential Practice 2 — Risk Assessment', owner: riskOfficer },
    { id: 'ctrl-ai6-3', name: 'AI6 Essential Practice 3 — Data Governance', owner: { name: 'Data Steward' } },
    { id: 'ctrl-ai6-4', name: 'AI6 Essential Practice 4 — Model Validation', owner: { name: 'Model Risk Lead' } },
    { id: 'ctrl-ai6-5', name: 'AI6 Essential Practice 5 — Monitoring', owner: { name: 'MLOps Lead' } },
    { id: 'ctrl-ai6-6', name: 'AI6 Essential Practice 6 — Incident Response', owner: { name: 'Security Operations' } },
  ];

  for (const p of ai6) {
    insertControl.run(p.id, p.name, 'NAIC AI6 essential practice control', serializeNamedOwner(p.owner), 'NAIC-AI6', ts, ts);
  }

  const capId = 'cap-llm-assist';
  db.prepare(`
    INSERT INTO capabilities (id, name, description, owner, status, category, metadata_json, created_at, updated_at)
    VALUES (?, 'Generative LLM Customer Assist', 'Customer-facing LLM capability', ?, 'PROPOSED', 'GENERATIVE_AI', '{}', ?, ?)
  `).run(capId, serializeNamedOwner({ name: 'Product AI Owner' }), ts, ts);

  for (const g of guardrails.slice(0, 3)) {
    db.prepare('INSERT INTO capability_controls (capability_id, control_id) VALUES (?, ?)').run(capId, g.id);
  }

  db.prepare(`
    INSERT INTO solutions (id, name, description, owner, stage, risk_tier, status, metadata_json, created_at, updated_at)
    VALUES ('sol-demo', 'NAIC-Aligned AI Solution (Demo)', 'Pre-seeded working group solution', ?, 1, 'MEDIUM', 'DRAFT', '{}', ?, ?)
  `).run(serializeNamedOwner({ name: 'Working Group Secretariat' }), ts, ts);

  db.prepare('INSERT INTO solution_capabilities (solution_id, capability_id) VALUES (?, ?)').run('sol-demo', capId);
}

export function listSolutions(): Solution[] {
