  return rows.map((r) => rowToSolution(r as Record<string, unknown>));
}

export function getSolution(id: string): Solution | undefined {
  const row = db.prepare('SELECT * FROM solutions WHERE id = ?').get(id);
  return row ? rowToSolution(row as Record<string, unknown>) : undefined;
}

export function createSolution(input: CreateSolutionInput): Solution {
  const id = randomUUID();
  const ts = nowIso();
  db.prepare(`
    INSERT INTO solutions (id, name, description, owner, stage, risk_tier, status, metadata_json, created_at, updated_at)
    VALUES (?, ?, ?, ?, 1, ?, 'DRAFT', ?, ?, ?)
  `).run(
    id,
    input.name,
    input.description ?? '',
    serializeNamedOwner(input.owner),
    input.riskTier ?? 'MEDIUM',
    JSON.stringify(input.metadata ?? {}),
    ts,
    ts
  );
  return getSolution(id)!;
}

export function updateSolution(id: string, input: UpdateSolutionInput): Solution {
  const existing = getSolution(id);
  if (!existing) throw new Error('Solution not found');

  const updated: Solution = {
    ...existing,
    ...input,
    owner: input.owner ?? existing.owner,
    approvedBy: input.approvedBy !== undefined ? input.approvedBy : existing.approvedBy,
    updatedAt: nowIso(),
  };

  db.prepare(`
    UPDATE solutions SET
      name = ?, description = ?, owner = ?, stage = ?, risk_tier = ?, status = ?,
      approved_by = ?, approved_at = ?, metadata_json = ?, updated_at = ?
    WHERE id = ?
  `).run(
    updated.name,
    updated.description,
    serializeNamedOwner(updated.owner),
    updated.stage,
    updated.riskTier,
    updated.status,
    updated.approvedBy ? serializeNamedOwner(updated.approvedBy) : null,
    updated.approvedAt ?? null,
    JSON.stringify(updated.metadata ?? {}),
    updated.updatedAt,
    id
  );

  return getSolution(id)!;
}

export function setSolutionStage(id: string, stage: SolutionStage): Solution {
