export function countActiveControlsForCapability(capabilityId: string): number {
  const row = db.prepare(`
    SELECT COUNT(*) AS c FROM capability_controls cc
    JOIN controls c ON c.id = cc.control_id
    WHERE cc.capability_id = ? AND c.status = 'ACTIVE'
  `).get(capabilityId) as { c: number };
  return row.c;
}

export function validateSolutionStageAdvance(solutionId: string, targetStage: SolutionStage): string | null {
  const capCount = countSolutionCapabilities(solutionId);
  if (targetStage > 4 && capCount < 1) {
    return 'Solution cannot advance past Stage 4 without at least one linked Capability';
  }
  if (targetStage >= 5 || targetStage === 7) {
    const caps = getSolutionCapabilities(solutionId);
    if (caps.length === 0) return 'Solution requires capabilities before Stage 5 or approval';
    for (const cap of caps) {
      if (countActiveControlsForCapability(cap.id) < 1) {
        return `Capability "${cap.name}" lacks an active Control`;
      }
    }
  }
  return null;
}

export function validateCapabilityAuthorisation(capabilityId: string): string | null {
  if (countActiveControlsForCapability(capabilityId) < 1) {
    return 'Capability cannot be AUTHORISED without at least one active Control';
  }
  return null;
}

