function getSolutionCapabilities(solution: Solution): Capability[] {
  return solution.capabilityIds
    .map((id) => getCapability(id))
    .filter((c): c is Capability => c !== undefined);
}

function capabilityHasActiveControl(capabilityId: string): boolean {
  const controls = listControls().filter((c) => c.capabilityId === capabilityId);
  return controls.some((c) => c.status === 'ACTIVE');
}

function assertSolutionStageInvariants(solution: Solution, nextStage: SolutionStage): void {
  const nextIdx = stageIndex(nextStage);
  const caps = getSolutionCapabilities(solution);

  if (nextIdx > stageIndex('IDENTIFY_CAPABILITIES') && caps.length < 1) {
    throw invariantError('Solution cannot advance past IDENTIFY_CAPABILITIES without at least one linked Capability');
  }

  if (nextIdx > stageIndex('APPLY_CONTROLS')) {
    const allControls = listControls();
    const hasAnyControl = caps.some((cap) => allControls.some((ctrl) => ctrl.capabilityId === cap.id));
    if (!hasAnyControl) {
      throw invariantError('Solution cannot advance past APPLY_CONTROLS without at least one Control on linked Capabilities');
    }
    for (const cap of caps) {
      if (!capabilityHasActiveControl(cap.id)) {
        throw invariantError(`Capability "${cap.name}" requires an active Control before the Solution advances past APPLY_CONTROLS`);
      }
    }
  }

  if (nextStage === 'APPROVE') {
    const allControls = listControls();
    const hasAnyControl = caps.some((cap) => allControls.some((ctrl) => ctrl.capabilityId === cap.id));
    if (!hasAnyControl) {
      throw invariantError('Solution cannot be approved without at least one Control on linked Capabilities');
    }
    for (const cap of caps) {
      if (!capabilityHasActiveControl(cap.id)) {
        throw invariantError(`Capability "${cap.name}" requires an active Control before Solution approval`);
      }
    }
  }
}

function assertCapabilityAuthorisation(capabilityId: string, nextStatus: CapabilityStatus): void {
  if (nextStatus !== 'AUTHORISED') return;
  if (!capabilityHasActiveControl(capabilityId)) {
    throw invariantError('Capability cannot be set to AUTHORISED without at least one active Control');
  }
}

function syncCapabilityControlIds(capabilityId: string): void {
  const controlIds = listControls()
    .filter((c) => c.capabilityId === capabilityId)
    .map((c) => c.id);
  const ts = now();
  db.prepare('UPDATE capabilities SET control_ids = ?, updated_at = ? WHERE id = ?').run(
    JSON.stringify(controlIds),
    ts,
    capabilityId
  );
}

function syncSolutionCapabilityIds(solutionId: string): void {
  const solution = getSolution(solutionId);
  if (!solution) return;
  const ts = now();
  db.prepare('UPDATE solutions SET capability_ids = ?, updated_at = ? WHERE id = ?').run(
    JSON.stringify(solution.capabilityIds),
    ts,
    solutionId
  );
}

export function initDatabase(dbPath = ':memory:'): DatabaseSync {
  db = new DatabaseSync(dbPath);
  db.exec('PRAGMA foreign_keys = ON');

  db.exec(`
    CREATE TABLE IF NOT EXISTS solutions (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      stage TEXT NOT NULL DEFAULT 'REQUEST',
      risk_tier TEXT NOT NULL DEFAULT 'LOW',
      owner TEXT NOT NULL,
      capability_ids TEXT NOT NULL DEFAULT '[]',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS capabilities (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      status TEXT NOT NULL DEFAULT 'DRAFT',
      owner TEXT NOT NULL,
      control_ids TEXT NOT NULL DEFAULT '[]',
      naic_guardrail_ids TEXT NOT NULL DEFAULT '[]',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS controls (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      status TEXT NOT NULL DEFAULT 'PENDING',
      owner TEXT NOT NULL,
      capability_id TEXT NOT NULL,
      guardrail_ref TEXT,
      essential_practice_ref TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      FOREIGN KEY (capability_id) REFERENCES capabilities(id)
    );

    CREATE TABLE IF NOT EXISTS governance_requests (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      status TEXT NOT NULL DEFAULT 'OPEN',
      requester TEXT NOT NULL,
      solution_id TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS meeting_decisions (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      decision TEXT NOT NULL,
      attendees TEXT NOT NULL DEFAULT '[]',
      solution_id TEXT,
      decided_at TEXT NOT NULL,
      created_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS risk_assessments (
      id TEXT PRIMARY KEY,
      solution_id TEXT NOT NULL,
      risk_tier TEXT NOT NULL,
      naic_alignment TEXT NOT NULL DEFAULT '',
      findings TEXT NOT NULL DEFAULT '',
      assessor TEXT NOT NULL,
      assessed_at TEXT NOT NULL,
      created_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS breaches (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      severity TEXT NOT NULL DEFAULT 'MINOR',
      status TEXT NOT NULL DEFAULT 'REPORTED',
      capability_id TEXT,
      control_id TEXT,
      reporter TEXT NOT NULL,
      reported_at TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS remediations (
      id TEXT PRIMARY KEY,
      breach_id TEXT NOT NULL,
      action TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'PLANNED',
      owner TEXT NOT NULL,
      due_date TEXT,
      completed_at TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      FOREIGN KEY (breach_id) REFERENCES breaches(id)
    );

    CREATE TABLE IF NOT EXISTS compliance_audits (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      checklist TEXT NOT NULL DEFAULT '[]',
      auditor TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'DRAFT',
      completed_at TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS naic_guardrails (
      id TEXT PRIMARY KEY,
      code TEXT NOT NULL,
      title TEXT NOT NULL,
      description TEXT NOT NULL,
      environment TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS essential_practices (
      id TEXT PRIMARY KEY,
      code TEXT NOT NULL,
      title TEXT NOT NULL,
      description TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS working_group_nodes (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      parent_id TEXT,
      role TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS bitbop_attestations (
      id TEXT PRIMARY KEY,
      event_type TEXT NOT NULL,
      entity_type TEXT NOT NULL,
      entity_id TEXT NOT NULL,
      beacon_sequence INTEGER NOT NULL,
      receipt TEXT NOT NULL,
      verified INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL
    );
  `);

  seedReferenceData();
  return db;
}

