  if (guardrailCount.c > 0) return;

  const insertGuardrail = db.prepare(
    'INSERT INTO naic_guardrails (id, code, title, description, environment) VALUES (?, ?, ?, ?, ?)'
  );
  const guardrails: Omit<NaicGuardrail, 'id'>[] = [
    { code: 'G1', title: 'Governance Framework', description: 'Establish AI governance framework and accountability', environment: 'BOTH' },
    { code: 'G2', title: 'Risk Assessment', description: 'Conduct risk assessments for AI systems', environment: 'BOTH' },
    { code: 'G3', title: 'Data Quality', description: 'Ensure data quality and integrity for AI models', environment: 'BOTH' },
    { code: 'G4', title: 'Transparency', description: 'Provide transparency on AI use to stakeholders', environment: 'BOTH' },
