    { code: 'G8-DEV', title: 'Development Lifecycle Controls', description: 'Apply controls during AI development lifecycle', environment: 'DEV' },
    { code: 'G8-DEP', title: 'Deployment Lifecycle Controls', description: 'Apply controls during AI deployment lifecycle', environment: 'DEP' },
    { code: 'G9', title: 'Incident Response', description: 'Maintain AI incident response procedures', environment: 'BOTH' },
    { code: 'G10', title: 'Continuous Monitoring', description: 'Continuously monitor AI system performance and drift', environment: 'BOTH' },
  ];
  for (const g of guardrails) {
    insertGuardrail.run(randomUUID(), g.code, g.title, g.description, g.environment);
  }

  const insertPractice = db.prepare(
    'INSERT INTO essential_practices (id, code, title, description) VALUES (?, ?, ?, ?)'
  );
  const practices: Omit<EssentialPractice, 'id'>[] = [
    { code: 'AI6-1', title: 'Inventory AI Systems', description: 'Maintain an inventory of all AI systems in use' },
    { code: 'AI6-2', title: 'Define Use Cases', description: 'Document approved AI use cases and boundaries' },
    { code: 'AI6-3', title: 'Assign Ownership', description: 'Assign named owners for each AI capability' },
    { code: 'AI6-4', title: 'Implement Controls', description: 'Apply NAIC-aligned controls to AI capabilities' },
    { code: 'AI6-5', title: 'Monitor & Report', description: 'Monitor AI systems and report breaches promptly' },
    { code: 'AI6-6', title: 'Review & Improve', description: 'Conduct periodic governance reviews and improvements' },
  ];
  for (const p of practices) {
    insertPractice.run(randomUUID(), p.code, p.title, p.description);
  }

  const insertWg = db.prepare(
    'INSERT INTO working_group_nodes (id, name, parent_id, role) VALUES (?, ?, ?, ?)'
  );
  const wgRoot = randomUUID();
  const wgChair = randomUUID();
  const wgTech = randomUUID();
  const wgRisk = randomUUID();
  insertWg.run(wgRoot, 'AI Working Group', null, 'Governance Body');
  insertWg.run(wgChair, 'Working Group Chair', wgRoot, 'Chair');
  insertWg.run(wgTech, 'Technical Subcommittee', wgRoot, 'Technical Review');
  insertWg.run(wgRisk, 'Risk & Compliance Subcommittee', wgRoot, 'Risk Assessment');
}

