// --- Solutions ---

export function listSolutions(): Solution[] {
  const rows = getDatabase().prepare('SELECT * FROM solutions ORDER BY created_at DESC').all();
  return rows.map((r) => mapSolutionRow(r as Record<string, unknown>));
}

export function getSolution(id: string): Solution | undefined {
  const row = getDatabase().prepare('SELECT * FROM solutions WHERE id = ?').get(id);
  return row ? mapSolutionRow(row as Record<string, unknown>) : undefined;
}

export function createSolution(input: CreateSolutionInput): Solution {
  const id = randomUUID();
  const ts = now();
  getDatabase()
    .prepare(
      `INSERT INTO solutions (id, title, description, stage, risk_tier, owner, capability_ids, created_at, updated_at)
       VALUES (?, ?, ?, 'REQUEST', ?, ?, '[]', ?, ?)`
    )
    .run(
      id,
      input.title,
      input.description ?? '',
      input.riskTier ?? 'LOW',
      serializeNamedOwner(input.owner),
      ts,
      ts
    );
  return getSolution(id)!;
}

export function updateSolution(id: string, input: UpdateSolutionInput): Solution {
  const existing = getSolution(id);
  if (!existing) throw new Error('Solution not found');

  if (input.stage && input.stage !== existing.stage) {
    assertSolutionStageInvariants(existing, input.stage);
  }

  const ts = now();
  getDatabase()
    .prepare(
      `UPDATE solutions SET
        title = COALESCE(?, title),
        description = COALESCE(?, description),
        stage = COALESCE(?, stage),
        risk_tier = COALESCE(?, risk_tier),
        owner = COALESCE(?, owner),
        updated_at = ?
       WHERE id = ?`
    )
    .run(
      input.title ?? null,
      input.description ?? null,
      input.stage ?? null,
      input.riskTier ?? null,
      input.owner ? serializeNamedOwner(input.owner) : null,
      ts,
      id
    );
  return getSolution(id)!;
}

export function linkCapabilityToSolution(solutionId: string, capabilityId: string): Solution {
  const solution = getSolution(solutionId);
  if (!solution) throw new Error('Solution not found');
  if (!getCapability(capabilityId)) throw new Error('Capability not found');
  if (!solution.capabilityIds.includes(capabilityId)) {
    solution.capabilityIds.push(capabilityId);
    const ts = now();
    getDatabase()
      .prepare('UPDATE solutions SET capability_ids = ?, updated_at = ? WHERE id = ?')
      .run(JSON.stringify(solution.capabilityIds), ts, solutionId);
  }
  return getSolution(solutionId)!;
}

export function unlinkCapabilityFromSolution(solutionId: string, capabilityId: string): Solution {
  const solution = getSolution(solutionId);
  if (!solution) throw new Error('Solution not found');
  const ts = now();
  const nextIds = solution.capabilityIds.filter((cid) => cid !== capabilityId);
  getDatabase()
    .prepare('UPDATE solutions SET capability_ids = ?, updated_at = ? WHERE id = ?')
    .run(JSON.stringify(nextIds), ts, solutionId);
  return getSolution(solutionId)!;
}

